
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All": {
        "Claimed": "SELECT 1 WHERE 1 = 0",
        "Unclaimed": "SELECT 1 WHERE 1 = 0",
        "All": "with base_data as ( SELECT hiproinst.proc_def_key_, hiproinst.tenant_id_, hiproinst.state_, hiproinst.end_time_ as \\"Closed Date\\", hiproinst.start_time_  AS \\"Created Date\\", hiproinst.proc_inst_id_ AS \\"Instance ID\\", MAX(CASE WHEN vars.name_ = ''payer'' THEN vars.text_ END) AS \\"Payer\\", MAX(CASE WHEN vars.name_ = ''payee'' THEN vars.text_ END) AS \\"Payee\\", MAX(CASE WHEN vars.name_ = ''TransactionAmount'' THEN vars.double_ / 100 END) AS \\"Amount\\", MAX(CASE WHEN vars.name_ = ''TicketID'' THEN vars.long_ END) AS \\"Case ID\\", MAX(CASE WHEN vars.name_ = ''Alert'' THEN vars.text_ END) AS \\"Alert\\", MAX(CASE WHEN vars.name_ = ''basedon'' THEN vars.text_ END) AS \\"Alert Type\\", MAX(CASE WHEN vars.name_ = ''address'' THEN vars.text_ END) AS \\"Address\\", ''Closed'' AS \\"Stage\\", null AS \\"Claimed By\\", ''Closed'' AS \\"Status\\", null AS \\"Claimed On\\" FROM t8refined.camunda.act_hi_procinst hiproinst JOIN t8refined.camunda.act_hi_varinst vars ON vars.proc_inst_id_ = hiproinst.proc_inst_id_ and vars.name_ in (''payer'',''payee'',''TransactionAmount'',''TicketID'',''Alert'',''basedon'',''address'') WHERE hiproinst.start_time_ >= :StartDate AND hiproinst.start_time_ < :EndDate AND hiproinst.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM postgresql.ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM postgresql.ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hiproinst.tenant_id_ = :tenantidstr GROUP BY 1,2,3,4,5,6 ORDER BY hiproinst.start_time_ LIMIT 65000 ), ranked_closedby AS ( SELECT proc_inst_id_, assignee_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC ) AS rn FROM t8refined.camunda.act_hi_taskinst WHERE proc_inst_id_ IN ( SELECT \\"Instance ID\\" FROM base_data ) ), pdef AS ( SELECT workflowkey, workflowname FROM postgresql.ui.workflowmasters where workflowkey in (select distinct proc_def_key_ from base_data) and itenantid = :tenantid ) SELECT CASE WHEN bd.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", bd.\\"Closed Date\\", bd.\\"Stage\\", bd.\\"Claimed By\\", bd.\\"Created Date\\", bd.\\"Status\\", pdef.workflowname as \\"Case Type\\", bd.\\"Claimed On\\", bd.\\"Payer\\", bd.\\"Payee\\", bd.\\"Amount\\", bd.\\"Case ID\\", bd.\\"Alert\\", bd.\\"Alert Type\\", bd.\\"Address\\" FROM base_data bd LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = bd.\\"Instance ID\\" AND closedby.rn = 1 LEFT JOIN postgresql.ui.webuser wuser ON wuser.iuserid = CAST(closedby.assignee_ AS INTEGER) LEFT JOIN pdef ON pdef.workflowkey = bd.proc_def_key_",
        "Closed": "with base_data as ( SELECT hiproinst.proc_def_key_, hiproinst.tenant_id_, hiproinst.state_, hiproinst.end_time_ as \\"Closed Date\\", hiproinst.start_time_  AS \\"Created Date\\", hiproinst.proc_inst_id_ AS \\"Instance ID\\", MAX(CASE WHEN vars.name_ = ''payer'' THEN vars.text_ END) AS \\"Payer\\", MAX(CASE WHEN vars.name_ = ''payee'' THEN vars.text_ END) AS \\"Payee\\", MAX(CASE WHEN vars.name_ = ''TransactionAmount'' THEN vars.double_ / 100 END) AS \\"Amount\\", MAX(CASE WHEN vars.name_ = ''TicketID'' THEN vars.long_ END) AS \\"Case ID\\", MAX(CASE WHEN vars.name_ = ''Alert'' THEN vars.text_ END) AS \\"Alert\\", MAX(CASE WHEN vars.name_ = ''basedon'' THEN vars.text_ END) AS \\"Alert Type\\", MAX(CASE WHEN vars.name_ = ''address'' THEN vars.text_ END) AS \\"Address\\", ''Closed'' AS \\"Stage\\", null AS \\"Claimed By\\", ''Closed'' AS \\"Status\\", null AS \\"Claimed On\\" FROM t8refined.camunda.act_hi_procinst hiproinst JOIN t8refined.camunda.act_hi_varinst vars ON vars.proc_inst_id_ = hiproinst.proc_inst_id_ and vars.name_ in (''payer'',''payee'',''TransactionAmount'',''TicketID'',''Alert'',''basedon'',''address'') WHERE hiproinst.start_time_ >= :StartDate AND hiproinst.start_time_ < :EndDate AND hiproinst.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM postgresql.ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM postgresql.ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hiproinst.tenant_id_ = :tenantidstr GROUP BY 1,2,3,4,5,6 ORDER BY hiproinst.start_time_ LIMIT 65000 ), ranked_closedby AS ( SELECT proc_inst_id_, assignee_, ROW_NUMBER() OVER ( PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC ) AS rn FROM t8refined.camunda.act_hi_taskinst WHERE proc_inst_id_ IN ( SELECT \\"Instance ID\\" FROM base_data ) ), pdef AS ( SELECT workflowkey, workflowname FROM postgresql.ui.workflowmasters where workflowkey in (select distinct proc_def_key_ from base_data) and itenantid = :tenantid ) SELECT CASE WHEN bd.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", bd.\\"Closed Date\\", bd.\\"Stage\\", bd.\\"Claimed By\\", bd.\\"Created Date\\", bd.\\"Status\\", pdef.workflowname as \\"Case Type\\", bd.\\"Claimed On\\", bd.\\"Payer\\", bd.\\"Payee\\", bd.\\"Amount\\", bd.\\"Case ID\\", bd.\\"Alert\\", bd.\\"Alert Type\\", bd.\\"Address\\" FROM base_data bd LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = bd.\\"Instance ID\\" AND closedby.rn = 1 LEFT JOIN postgresql.ui.webuser wuser ON wuser.iuserid = CAST(closedby.assignee_ AS INTEGER) LEFT JOIN pdef ON pdef.workflowkey = bd.proc_def_key_"
